/**
 * The AI's icon: the cat in the frame, 512x512.
 *
 * Embedded as text rather than kept as an image file so the backend can serve
 * it from memory (GET /ai-icon.jpg) with nothing to find on disk and no
 * dependence on Git LFS, which this repo uses for .jpg files. The stand-alone
 * pages load their own file copies, written from this by scripts/sync-ambient.mjs.
 */
export const AI_ICON_JPEG_BASE64 =
  "";

export const AI_ICON_JPEG: Buffer = Buffer.from(AI_ICON_JPEG_BASE64, "base64");
